{
  "name": "@hmanzano1012/opencode-cursor-oauth",
  "version": "0.5.1",
  "description": "OpenCode plugin that connects Cursor's API to OpenCode via OAuth, model discovery, and a local OpenAI-compatible proxy.",
  "license": "MIT",
  "author": "HManzano1012",
  "type": "module",
  "main": "./dist/index.js",
  "module": "./dist/index.js",
  "types": "./dist/index.d.ts",
  "exports": {
    ".": {
      "types": "./dist/index.d.ts",
      "import": "./dist/index.js",
      "default": "./dist/index.js"
    },
    "./server": {
      "types": "./dist/server.d.ts",
      "import": "./dist/server.js",
      "default": "./dist/server.js"
    }
  },
  "engines": {
    "opencode": ">=1.14.18"
  },
  "oc-plugin": [
    "server"
  ],
  "files": [
    "dist"
  ],
  "scripts": {
    "build": "node ./scripts/build.mjs",
    "test": "bun test",
    "prepublishOnly": "npm run build"
  },
  "repository": {
    "type": "git",
    "url": "git+https://github.com/HManzano1012/opencode-cursor.git"
  },
  "homepage": "https://github.com/HManzano1012/opencode-cursor#readme",
  "bugs": {
    "url": "https://github.com/HManzano1012/opencode-cursor/issues"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "cursor",
    "oauth",
    "openai-compatible"
  ],
  "publishConfig": {
    "access": "public"
  },
  "dependencies": {
    "@bufbuild/protobuf": "^2.0.0",
    "@opencode-ai/plugin": "^1.16.2",
    "zod": "^3.24.0"
  },
  "devDependencies": {
    "@types/bun": "^1.3.11",
    "typescript": "^5.9.3"
  }
}
